head.script:
/* 프로그램ID */
scwin.pgmId = 'PGJ111P09';

/*최상단 선언 */
scwin.isMain = function() {
	return true;
};

scwin.result = '';

/**
 * 투표 onpageLoad
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.08.14.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.onpageload = function() {
	setTimeout(function(){
        pgjUtil.setPopUpCloseNextTabEvent($p.getFrame());
    }, 500);
	const userId = WebSquare.cookie.getCookie('cortAuctnLgnMbr')
	scscrno.setScPgmId(scwin.pgmId);
	scglblo.setScUserId(userId);
	com.executeSubmission(sbm_selectNwstVtInf)
};

scwin.onpageunload = function() {

};


/**
 * 최신정보 투표조회후 데이터 셋팅
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.08.14.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.sbm_selectNwstVtInf_submitdone = function({responseJSON:{data,status,message}}) {
	if (status === 200) {
		scwin.result = data.result
		const item = scwin.result.vtItm
		const itemLst = scwin.result.vtItmLst
		tbx_title.setValue(item.vtTitlNm);
		let ymd = `${scdateo.getFmtDate(item.bgngYmd)} ~ ${scdateo.getFmtDate(item.endYmd)}`
		spn_srvyPerd.setValue(ymd)
		itemLst.forEach(r=>{
			rad_vtItem.addItem(r.cortAuctnVtQstnVsbeSeq, r.vtItmVsbeCtt)
		})
		/* 현재 투표결과 내역 */
		scwin.reloadGraph(itemLst)
	} else {
		scutilo.showMsg(scglblo.MSG.WARN,message);
	}
};

/**
 * '투표하기 버튼 클릭시 사용자의 투표정보 insert'
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.08.14.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.btn_vtSave_onclick = function(e) {
	/* TO-DO 로그인 여부 체크후 실행 일단은 TRUE처리*/
	if (rad_vtItem.getSelectedIndex() === -1) {
		scutilo.showMsg(scglblo.MSG.WARN,scutilo.getMsg(pgjmsg.PGJ.W_0061))
		return
	} else {
		 pgjUtil.loginCheckMoveLoginPage().then(result =>{
			if(result){
				//투표진행
				const item = scwin.result.vtItm
				const value = {
					cortAuctnVtSrno : item.cortAuctnVtSrno,
					cortAuctnVtQstnSeq : item.cortAuctnVtQstnSeq,
					cortAuctnVtQstnVsbeSeq : rad_vtItem.getValue(),
					cortAuctnMbrsId : WebSquare.cookie.getCookie('cortAuctnLgnMbr'),
				}
				dma_saveVt.setJSON(value);
				com.executeSubmission(sbm_insertMbrsVt);
			} else {
				return;
			}
		});
	}
};

/**
 *  투표정보 저장후에 확인메세지와 투표결과 최신내역 반영
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.08.14.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.sbm_insertMbrsVt_submitdone = function({responseJSON:{data:{result},status,message}}) {
	if (status === 200) {
		scutilo.showMsg(scglblo.MSG.INFO,message);
	} else {
		scutilo.showMsg(scglblo.MSG.WARN,message);
	}
	const vtLst = result.vtItmLst;
	/* 투표결과 내역 reload */
	scwin.reloadGraph(vtLst)
};

/**
 * 투표결과 반영하는 메서드
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.08.14.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.reloadGraph = function(itemLst) {
	gen_prBar.removeAll();
	if (itemLst.length>0) {
		itemLst.forEach((r,i)=>{
			gen_prBar.insertChild(i);
			gen_prBar.getChild(i, 'tbx_barTitle').setValue(r.vtItmVsbeCtt)
			gen_prBar.getChild(i, 'spn_barRate').setValue(`${r.rate}%`)
			gen_prBar.getChild(i, 'spn_barCnt').setValue(`(${r.bogiCnt}명)`)
			gen_prBar.getChild(i, 'grp_barGraph').setStyle('width', `${r.rate}%`);
		})
	}
}
